import './App.css';
import { Link, Outlet, Route, Routes } from 'react-router-dom';
import { Fragment, useState } from 'react';

const WEEKDAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

function isoWeekNumber(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const dayNum = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil(((d - yearStart) / 86400000 + 1) / 7);
}

function buildCalendarWeeks(year, month) {
  const firstOfMonth = new Date(year, month, 1);
  const offset = (firstOfMonth.getDay() + 6) % 7;
  const cur = new Date(year, month, 1 - offset);
  const monthEnd = new Date(year, month + 1, 0);
  const weeks = [];
  while (true) {
    const row = [];
    for (let i = 0; i < 7; i += 1) {
      row.push(new Date(cur));
      cur.setDate(cur.getDate() + 1);
    }
    if (row[0] > monthEnd) break;
    weeks.push(row);
  }
  return weeks;
}

function calendarDayKey(d) {
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
}

const TEACHER_FUTURE_EVENTS_SEED = [
  { id: 'future-1', name: 'Differentiated Instruction Workshop', date: '2026-05-15' },
  { id: 'future-2', name: 'STEM Integration PD Day', date: '2026-06-03' },
  { id: 'future-3', name: 'Classroom Technology Lab', date: '2026-06-20' },
];

